import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/corelib/commands.md","filePath":"en/modules/corelib/commands.md","lastUpdated":0}`),a={name:`en/modules/corelib/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>Every CoreLib command and permission node is listed below, followed by the operations you will use most</p><p>The main command of EmakiCoreLib is <code>/emakicorelib</code>, with <code>/corelib</code> and <code>/emakicore</code> as aliases. You use these commands as a server administrator to reload CoreLib, run config prechecks (an early pass that checks your configuration for you), list or execute registered Actions, and troubleshoot loop Action tasks</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/corelib reload</code></td><td><code>emakicorelib.reload</code> or <code>emakicorelib.admin</code></td><td>Reload CoreLib configuration and the Action system. If precheck fails, the previous config remains active</td></tr><tr><td><code>/corelib check [module|report|--fix]</code></td><td><code>emakicorelib.admin</code></td><td>Run config prechecks, check one module, or show the latest report. <code>--fix</code> really applies the fixes (creating missing config files, directories, and keys), prints the fixed/failed counts, and then re-runs the check</td></tr><tr><td><code>/corelib action list</code></td><td><code>emakicorelib.admin</code></td><td>List registered stages with id, kind (<code>source</code>/<code>gate</code>/<code>action</code>), and owner</td></tr><tr><td><code>/corelib action run &lt;actionId&gt; key=value ...</code></td><td><code>emakicorelib.admin</code></td><td>Execute one currently registered Action. <code>/corelib action &lt;actionId&gt; key=value ...</code> is also accepted as shorthand</td></tr><tr><td><code>/corelib pdc-convert &lt;players|containers|entities|all&gt; [--dry-run]</code></td><td><code>emakicorelib.admin</code></td><td>Convert legacy dotted PDC keys to flat keys. <code>--dry-run</code> only counts and writes nothing</td></tr><tr><td><code>/corelib debug all [on|off|status]</code></td><td><code>emakicorelib.admin</code></td><td>Toggle the global Debug switch at runtime. Without an argument it behaves as <code>status</code>. A reload restores the configured <code>debug.global_all</code> value</td></tr><tr><td><code>/corelib debug loops [list|player|key|cancel|cancel-player]</code></td><td><code>emakicorelib.admin</code></td><td>Inspect active loop Action tasks and cancel them by key or player</td></tr><tr><td><code>/corelib help</code></td><td>none</td><td>Show subcommand help. Also shown when no argument or an unknown subcommand is given</td></tr></tbody></table><p>There are two spellings for the same thing: the <code>action</code> subcommand may also be written as <code>actions</code>, and both are equivalent</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakicorelib.reload</code></td><td>op</td><td>Allows CoreLib reload</td></tr><tr><td><code>emakicorelib.admin</code></td><td>op</td><td>Administrative fallback permission; includes <code>emakicorelib.reload</code></td></tr></tbody></table><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to “Common operations”">​</a></h2><h3 id="reload-corelib" tabindex="-1">Reload CoreLib <a class="header-anchor" href="#reload-corelib" aria-label="Permalink to “Reload CoreLib”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib reload</span></span></code></pre></div><p>Run it whenever you change CoreLib configuration, language files, or Actions. Reload runs a config precheck first; if the precheck fails, the currently active configuration is kept</p><h3 id="run-config-prechecks" tabindex="-1">Run config prechecks <a class="header-anchor" href="#run-config-prechecks" aria-label="Permalink to “Run config prechecks”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib check</span></span>
<span class="line"><span>/corelib check report</span></span>
<span class="line"><span>/corelib check corelib</span></span>
<span class="line"><span>/corelib check --fix</span></span></code></pre></div><p><code>check</code> validates configuration references, Action templates, item sources, and CoreLib-related settings. For the latest precheck result, use <code>report</code>; to check a single module, pass its module id. With <code>--fix</code> the fixes are actually written to disk, covering the three auto-fixable issue kinds only: missing default config files, missing directories, and missing config keys. It prints the fixed/failed counts and then re-runs the precheck so you see the result. Content that already exists and was edited by an administrator is never overwritten. Fixed files take effect after the owning module reloads or the server restarts</p><h3 id="list-and-execute-registered-actions" tabindex="-1">List and execute registered Actions <a class="header-anchor" href="#list-and-execute-registered-actions" aria-label="Permalink to “List and execute registered Actions”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib action list</span></span>
<span class="line"><span>/corelib action run send_message text=&quot;hello&quot;</span></span></code></pre></div><p>Use <code>action list</code> to confirm what is currently registered; each line prints id, kind, and owner. <code>action run</code> hands the whole line to the pipeline compiler as a normal pipeline line, so parameters, quoting, <code>if &lt;condition&gt; [ ... ]</code> branches, and gate syntax follow the same rules as pipeline lines you write in configuration files. Note that console execution has no player context, so stages that require a player fail through normal validation</p><h3 id="convert-legacy-pdc-keys" tabindex="-1">Convert legacy PDC keys <a class="header-anchor" href="#convert-legacy-pdc-keys" aria-label="Permalink to “Convert legacy PDC keys”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib pdc-convert players</span></span>
<span class="line"><span>/corelib pdc-convert containers</span></span>
<span class="line"><span>/corelib pdc-convert entities</span></span>
<span class="line"><span>/corelib pdc-convert all --dry-run</span></span></code></pre></div><p>Pick a scope first: one of <code>players</code>, <code>containers</code>, <code>entities</code>, or <code>all</code>. The conversion scans asynchronously and then reports scanned / migrated / skipped / failed counts per scope plus a total migrated count. Start with <code>--dry-run</code>, which only counts and writes nothing, so you can size the impact first</p><h3 id="debug-loop-actions" tabindex="-1">Debug loop Actions <a class="header-anchor" href="#debug-loop-actions" aria-label="Permalink to “Debug loop Actions”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib debug loops list</span></span>
<span class="line"><span>/corelib debug loops player Steve</span></span>
<span class="line"><span>/corelib debug loops key some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel some-loop-key</span></span>
<span class="line"><span>/corelib debug loops cancel-player Steve</span></span></code></pre></div><p>These commands exist only for troubleshooting or cleaning up loop Actions. Keep in mind that you should not leave large-scale loop task debugging enabled on production servers</p><h3 id="toggle-global-debug" tabindex="-1">Toggle global Debug <a class="header-anchor" href="#toggle-global-debug" aria-label="Permalink to “Toggle global Debug”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/corelib debug all status</span></span>
<span class="line"><span>/corelib debug all on</span></span>
<span class="line"><span>/corelib debug all off</span></span></code></pre></div><p>This does the same thing as temporarily overriding <code>debug.global_all</code> in <code>config.yml</code>, and it affects every Emaki module that uses CoreLib&#39;s <code>DebugLogger</code>. The toggle is not written back to the config file; running <code>/corelib reload</code> picks up the configured value again</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};